def is_woodall(n):
    """Return True if n is a Woodall number, else False."""
    if n <= 0:
        return False
    k = 1
    while True:
        w = (2 ** k) * k - 1
        if w == n:
            return True
        if w > n:
            return False
        k += 1
```

