    prev_row = [1]
    for i in range(1, n + 1):
        curr_row = [0] * (i + 1)
        curr_row[0] = prev_row[-1]
        for j in range(1, i + 1):
            curr_row[j] = prev_row[j - 1] + (curr_row[j - 1] if j > 0 else 0)
        prev_row = curr_row
    return prev_row[0]
