def bell_number(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1

    row = [0] * (n + 1)
    row[0] = 1

    for i in range(1, n + 1):
        new_row = [0] * (n + 1)
        new_row[0] = row[i - 1] if i - 1 < len(row) else 0
        for j in range(1, i + 1):
            new_row[j] = row[j - 1] + (row[j] if j < len(row) else 0)
        row = new_row

    return row[0]
```

