    if len(s) <= 2:
        return False
    # Pattern must be ABABAB... with A != B
    a, b = s[0], s[1]
    if a == b:
        return False
    for i in range(2, len(s)):
        if s[i] != a:
            return False
        if i % 2 == 1 and s[i] != b:
            return False
    return True
