def is_undulating(n):
    s = str(n)
    if len(s) <= 2:
        return False
    # Pattern must be ABAB... (two alternating digits)
    a, b = s[0], s[1]
    if a == b:
        return False
    for i in range(2, len(s)):
        if s[i] != b if i % 2 == 1 else s[i] != a:
            return False
    return True
