def odd_Equivalent(s,n): 
    if n == 0:
        return s.count('1')
    rot = min(n, len(s))
    cnt = 0
    for i in range(rot):
        if s[(i - rot) % len(s)] == '1':
            cnt += 1
    return cnt
```

