def find_length(s):
    max_diff = 0
    current_diff = 0

    # Scan from left to right
    for ch in s:
        if ch == '0':
            current_diff += 1
        else:
            current_diff -= 1
        if current_diff < 0:
            current_diff = 0
        max_diff = max(max_diff, current_diff)

    # Scan from right to left
    current_diff = 0
    for ch in reversed(s):
        if ch == '0':
            current_diff += 1
        else:
            current_diff -= 1
        if current_diff < 0:
            current_diff = 0
        max_diff = max(max_diff, current_diff)

    return max_diff
```

