def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        return None if n % b != 0 else (0, n // b)
    if b == 0:
        return None if n % a != 0 else (n // a, 0)

    # Extended Euclidean Algorithm to find x0, y0 such that a*x0 + b*y0 = gcd(a,b)
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        g, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return g, x, y

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None

    # Scale the solution to match n
    factor = n // g
    x = x0 * factor
    y = y0 * factor

    # Find the smallest non-negative x
    lcm = (a // g) * b
    x = x % lcm
    y = (n - a * x) // b

    return (x, y)
```

