def get_total_number_of_sequences(m, n):
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        dp[i][1] = 1
    for length in range(2, n + 1):
        for end in range(1, m + 1):
            start_min = 1
            if end >= 2:
                start_min = (end + 1) // 2
            for start in range(start_min, end + 1):
                dp[end][length] += dp[start][length - 1]
    return dp[m][n]
