def get_total_number_of_sequences(m, n):
    if n == 0:
        return 1 if m >= 1 else 0

    # dp[i][j] = number of valid sequences of length j ending with value i
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base case: sequences of length 1
    for i in range(1, m + 1):
        dp[i][1] = 1

    # Fill DP table
    for length in range(2, n + 1):
        for end_val in range(1, m + 1):
            start_min = 2 * (end_val // 2)  # smallest start such that 2*start <= end_val
            # But we need start >= 1 and 2*start <= end_val => start <= end_val // 2
            start_max = end_val // 2
            if start_max >= 1:
                # Sum dp[start][length-1] for start in [1, start_max]
                dp[end_val][length] = sum(dp[s][length - 1] for s in range(1, start_max + 1))

    # Sum over all possible last elements
    return sum(dp[i][n] for i in range(1, m + 1))
