    for j in range(2, n + 1):
        for i in range(1, m + 1):
            # previous element p must satisfy: i >= 2*p  => p <= i // 2
            if i >= 2:
                for p in range(1, i // 2 + 1):
                    dp[i][j] += dp[p][j - 1]

    # Sum over all possible last elements for length n
    return sum(dp[i][n] for i in range(1, m + 1))
