        for start in range(1, m + 1):
            if start * (1 << (length - 1)) > m:
                dp[start][length] = 0
                continue
            lower = start * (1 << (length - 1))
            upper = m
            if lower > upper:
                dp[start][length] = 0
            else:
                dp[start][length] = sum(dp[x][length - 1] for x in range(lower, upper + 1))

    return sum(dp[i][n] for i in range(1, m + 1))
