            return m - a + 1
        if a * 2 > m:
            return 0
        total = 0
        for nxt in range(a * 2, m + 1):
            total += count(nxt, k - 1)
        return total

    total = 0
    for first in range(1, m + 1):
        total += count(first, n)
    return total
