    if n == 0:
        return 0
    if n == 1:
        return k
    if n == 2:
        return k * k

    mod = 1000000007
    prev2 = k          # ways for i-2
    prev1 = k * k      # ways for i-1

    for i in range(3, n + 1):
        curr = ((k - 1) * (prev1 + prev2)) % mod
        prev2, prev1 = prev1, curr

    return prev1
