def get_max_sum(n):
    if n == 0:
        return 0
    memo = [0] * (n + 1)
    memo[1] = 1
    for i in range(2, n + 1):
        val = i
        if i // 2 >= 1:
            val += memo[i // 2]
        if i // 3 >= 1:
            val += memo[i // 3]
        if i // 4 >= 1:
            val += memo[i // 4]
        if i // 5 >= 1:
            val += memo[i // 5]
        memo[i] = max(i, val)
    return memo[n]
