def cal_sum(n):
    if n == 0:
        return 3
    if n == 1:
        return 3
    if n == 2:
        return 5

    # P(n) sequence: P(0)=3, P(1)=0, P(2)=2, P(3)=3, P(4)=5, P(5)=8, ...
    p = [0] * (n + 1)
    p[0] = 3
    p[1] = 0
    p[2] = 2
    for i in range(3, n + 1):
        p[i] = p[i - 2] + p[i - 3]

    return sum(p)
```

