def sumofFactors(n: int) -> int:
    if n <= 0:
        return 0
    result = 1
    d = 2
    while d * d <= n:
        if n % d == 0:
            power = 0
            while n % d == 0:
                n //= d
                power += 1
            # sum_{k=1..power} d^k = d * (d^power - 1) / (d - 1)
            term = d * (d ** power - 1) // (d - 1)
            result *= term
        d += 1
    if n > 1:
        result *= (n + 1)
    return result
```

