    if first == -1:
        return False
    last = last_occurrence(arr, n, x)
    return (last - first + 1) > n // 2

def first_occurrence(arr, n, x):
    left, right = 0, n - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            if mid == 0 or arr[mid - 1] != x:
                return mid
            right = mid - 1
        elif arr[mid] > x:
            right = mid - 1
        else:
            left = mid + 1
    return -1

def last_occurrence(arr, n, x):
    left, right = 0, n - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            if mid == n - 1 or arr[mid + 1] != x:
                return mid
            left = mid + 1
        elif arr[mid] > x:
            right = mid - 1
        else:
            left = mid + 1
    return -1
```

