def find_solution(a, b, n):
    import math

    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        return (0, n // b) if n % b == 0 else None
    if b == 0:
        return (n // a, 0) if n % a == 0 else None

    g = math.gcd(a, b)
    if n % g != 0:
        return None

    # Reduce to a'x + b'y = n' with gcd(a', b') = 1
    a //= g
    b //= g
    n //= g

    # Extended Euclidean to find u, v such that a*u + b*v = 1
    def ext_gcd(a, b):
        if b == 0:
            return (1, 0, a)
        u1, v1, g = ext_gcd(b, a % b)
        return (v1, u1 - (a // b) * v1, g)

    u0, v0, _ = ext_gcd(a, b)  # a*u0 + b*v0 = 1

    # Particular solution for a*x + b*y = n
    x0 = u0 * n
    y0 = v0 * n

    # General solution:
    # x = x0 + b*t
    # y = y0 - a*t
    # We can choose t to minimize |x| or just return one valid pair.
    return (x0, y0)
```

