def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        return None if n % b != 0 else (0, n // b)
    if b == 0:
        return None if n % a != 0 else (n // a, 0)

    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        g, x1, y1 = extended_gcd(y, x % y)
        return g, y1, x1 - (x // y) * y1

    g, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % g != 0:
        return None

    # Adjust signs
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    # Scale to match n
    x = x0 * (n // g)
    y = y0 * (n // g)

    # Find the smallest non-negative solution for x (optional, but keeps it tidy)
    # General solution: x = x0 + (b/g)*t, y = y0 - (a/g)*t
    step_x = b // g
    step_y = -a // g

    # Normalize x to be within [0, |step_x|)
    x = x % step_x if step_x > 0 else x % (-step_x)
    y = y - step_y * (x // step_x) if step_x > 0 else y - step_y * (x // step_x)

    return x, y
```

