def is_majority(arr, n, x):
    if n <= 0:
        return False
    left = arr.index(x) if x in arr else -1
    if left == -1:
        return False
    right = left
    while right + 1 < n and arr[right + 1] == x:
        right += 1
    count = right - left + 1
    return count > n // 2
