def get_max_sum(n: int) -> int:
    if n <= 0:
        return 0
    memo = {0: 0, 1: 1}

    def dp(k):
        if k in memo:
            return memo[k]
        res = max(k, dp(k // 2) + dp(k // 3) + dp(k // 4) + dp(k // 5))
        memo[k] = res
        return res

    return dp(n)
