def find_solution(a, b, n):
    import math

    def extended_gcd(aa, bb):
        if bb == 0:
            return aa, 1, 0
        g, x1, y1 = extended_gcd(bb, aa % bb)
        return g, y1, x1 - (aa // bb) * y1

    if a == 0:
        if b == 0:
            return None
        if n % b == 0:
            return (0, n // b)
        return None
    if b == 0:
        if a == 0:
            return None
        if n % a == 0:
            return (n // a, 0)
        return None

    g, x0, y0 = extended_gcd(abs(a), abs(b))

    if n % g != 0:
        return None

    # Scale the particular solution
    x = x0 * (n // g)
    y = y0 * (n // g)

    # Adjust signs if original a or b were negative
    if a < 0:
        x = -x
    if b < 0:
        y = -y

    return x, y
```

