def count_char_position(s: str) -> int:
    """
    Count how many characters appear at the same index in the string as in the alphabet.
    The alphabet is 0-indexed: 'a' or 'A' -> 0, 'b' or 'B' -> 1, ..., 'z' or 'Z' -> 25.
    Case-insensitive.
    """
    count = 0
    for i, ch in enumerate(s):
        if 'a' <= ch <= 'z':
            expected_index = ord(ch) - ord('a')
        elif 'A' <= ch <= 'Z':
            expected_index = ord(ch) - ord('A')
        else:
            continue

        if i == expected_index:
            count += 1
    return count
```

