def is_majority(arr, n, elem):
    if n == 0:
        return False
    left = 0
    right = n - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == elem:
            # Check the count of elem
            count = 1
            i = mid - 1
            while i >= 0 and arr[i] == elem:
                count += 1
                i -= 1
            j = mid + 1
            while j < n and arr[j] == elem:
                count += 1
                j += 1
            return count > n // 2
        elif arr[mid] < elem:
            left = mid + 1
        else:
            right = mid - 1
    return False
```

