def get_max_sum(n: int) -> int:
    memo = {0: 0, 1: 1}

    def f(x: int) -> int:
        if x in memo:
            return memo[x]
        option1 = x
        option2 = f(x // 2) + f(x // 3) + f(x // 4) + f(x // 5)
        memo[x] = max(option1, option2)
        return memo[x]

    return f(n)
```

```python
def get_max_sum(n: int) -> int:
    memo = {}

    def dp(x: int) -> int:
        if x <= 1:
            return x
        if x in memo:
            return memo[x]
        result = max(x, dp(x // 2) + dp(x // 3) + dp(x // 4) + dp(x // 5))
        memo[x] = result
        return result

    return dp(n)
```

