        raise ValueError("List must contain at least one element.")
    max_neg = float('-inf')
    for n in nums:
        if n < 0 and n > max_neg:
            max_neg = n
    if max_neg == float('-inf'):
        raise ValueError("List must contain at least one negative number.")
    return max_neg
```

