def cal_sum(n: int) -> int:
    """
    Return the sum of the first n+1 Perrin numbers (indices 0..n).

    Perrin sequence:
      P(0) = 3, P(1) = 0, P(2) = 2
      P(k) = P(k-2) + P(k-3) for k >= 3
    """
    if n < 0:
        return 0

    if n == 0:
        return 3
    if n == 1:
        return 3 + 0  # P(0) + P(1)
    if n == 2:
        return 3 + 0 + 2  # P(0)+P(1)+P(2)

    # Initialize first three
    p0, p1, p2 = 3, 0, 2
    total = p0 + p1 + p2

    for _ in range(3, n + 1):
        p3 = p1 + p0
        p0, p1, p2 = p1, p2, p3
        total += p2

    return total
```

