def search(arr):
    n = len(arr)
    if n == 0:
        return 0
    l, r = 0, n - 1
    while l <= r:
        mid = (l + r) // 2
        if mid % 2 == 1:
            mid -= 1
        if arr[mid] == arr[mid + 1]:
            l = mid + 2
        else:
            r = mid - 1
    return arr[l]
```

