def search(arr):
    n = len(arr)
    if n == 1:
        return arr[0] * 4
    left, right = 0, n - 1
    while left < right:
        mid = (left + right) // 2
        if arr[mid] == arr[mid + 1]:
            left = mid + 2
        else:
            right = mid - 1
    if left == n:
        return arr[n-1] * 4
    if left == 0:
        return arr[0] * 4
    return arr[left-1] * 4
```

