def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        return None if n % b != 0 else (0, n // b)
    if b == 0:
        return None if n % a != 0 else (n // a, 0)
    if a < 0:
        a, n = -a, -n
    if b < 0:
        b, n = -b, -n
    if n < 0:
        return None
    for x in range(n // a + 1):
        if (n - a * x) % b == 0:
            y = (n - a * x) // b
            return (x, y)
    return None
```

