def is_majority(arr, n, x):
    # Find the first occurrence of x
    low, high = 0, n - 1
    first = -1
    while low <= high:
        mid = (low + high) >> 1
        if arr[mid] == x:
            first = mid
            high = mid - 1
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1

    if first == -1:
        return False

    # Check the element at position first + n//2
    if first + n//2 >= n or arr[first + n//2] != x:
        return False

    return True
```

