def is_majority(arr, n, x):
    left = first_occurrence(arr, 0, n - 1, x)
    if left == -1:
        return False
    right = last_occurrence(arr, 0, n - 1, x)
    if right - left + 1 > n // 2:
        return True
    return False

def first_occurrence(arr, low, high, x):
    if high < low:
        return -1
    if arr[low] == x:
        return low
    if arr[high] != x:
        return -1
    mid = (low + high) // 2
    if arr[mid] == x:
        return first_occurrence(arr, low, mid - 1, x)
    return first_occurrence(arr, mid + 1, high, x)

def last_occurrence(arr, low, high, x):
    if high < low:
        return -1
    if arr[high] == x:
        return high
    if arr[low] != x:
        return -1
    mid = (low + high) // 2
    if arr[mid] == x:
        return last_occurrence(arr, mid + 1, high, x)
    return last_occurrence(arr, low, mid - 1, x)
```

